def mark_personal_addresses(apps, schema_editor):
    """
    Make each referee's address their personal address. An address that is
    also used elsewhere (a location, accommodation, examination or another
    referee) stays public, and the referee gets a personal copy of it.
    """
    Referee = apps.get_model("referee", "Referee")
    Examination = apps.get_model("referee", "Examination")
    Location = apps.get_model("helper", "Location")
    Accommodation = apps.get_model("competition", "Accommodation")
    for referee in Referee.objects.exclude(address=None).select_related("address"):
        address = referee.address
        if address.user_id == referee.user_id:
            continue
        shared = (
            address.user_id is not None
            or Location.objects.filter(address=address).exists()
            or Accommodation.objects.filter(address=address).exists()
            or Examination.objects.filter(address=address).exists()
            or Referee.objects.filter(address=address).exclude(pk=referee.pk).exists()
        )
        if shared:
            address.pk = None
            address.user_id = referee.user_id
            address.save()
            referee.address = address
            referee.save(update_fields=["address"])
        else:
            address.user_id = referee.user_id
            address.save(update_fields=["user"])


